```tsx
// Basic Usage
import { DataTable } from '@/lib/designsystem';
import { type ColumnDef } from '@tanstack/react-table';

interface User { id: string; name: string; email: string; role: string; }

const columns: ColumnDef<User>[] = [
  { accessorKey: 'name', header: 'Name' },
  { accessorKey: 'email', header: 'Email' },
  { accessorKey: 'role', header: 'Role' },
];

const data: User[] = [
  { id: '1', name: 'John Doe', email: 'john@example.com', role: 'Admin' },
  { id: '2', name: 'Jane Smith', email: 'jane@example.com', role: 'User' },
];

function UserTable() {
  return <DataTable columns={columns} data={data} showPagination={true} />;
}
```

```tsx
// With Row Selection and Actions
import { DataTable, DataTableSelectionAction } from '@/lib/designsystem';
import { Trash2 } from 'lucide-react';
// ... (User type, columns, data defined as above)

const handleBulkDelete = (selectedUsers: User[]) => {
  console.log('Deleting:', selectedUsers.map(u => u.id));
};

const selectionActions: DataTableSelectionAction<User>[] = [
  { label: 'Delete Selected', onClick: handleBulkDelete, icon: <Trash2 />, variant: 'danger' }
];

function SelectableUserTable() {
  return (
    <DataTable
      columns={columns}
      data={data}
      enableRowSelection={true}
      selectionActions={selectionActions}
      getRowId={(row) => row.id}
    />
  );
}
```

```tsx
// With Add Action and Filtering
import { DataTable, DataTableAddAction, FilterGroup } from '@/lib/designsystem';
import { Plus } from 'lucide-react';
// ... (User type, columns, data defined as above)

const handleAddItem = () => { console.log('Add item clicked'); };

const addAction: DataTableAddAction = {
  label: 'Add User',
  onClick: handleAddItem,
  icon: <Plus className="h-4 w-4 mr-1" />
};

const filterGroups: FilterGroup[] = [{
  id: 'role', label: 'Role', options: [
    { id: 'role-admin', label: 'Admin', value: 'Admin', column: 'role' },
    { id: 'role-user', label: 'User', value: 'User', column: 'role' }
  ]
}];

function FilterableUserTable() {
  return (
    <DataTable
      columns={columns}
      data={data}
      addAction={addAction}
      filterGroups={filterGroups}
    />
  );
}
